"""Notification config CRUD + test send."""

import json

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.ext.asyncio import AsyncSession

from .. import crud
from ..database import get_db
from ..schemas import NotificationCreate, NotificationRead, NotificationUpdate

router = APIRouter()


def _serialize_config(cfg) -> dict:
    """Deserialize config_json from DB string to dict for response."""
    data = {
        "id": cfg.id,
        "backend": cfg.backend,
        "enabled": cfg.enabled,
        "config_json": json.loads(cfg.config_json) if isinstance(cfg.config_json, str) else cfg.config_json,
        "created_at": cfg.created_at,
        "updated_at": cfg.updated_at,
    }
    return data


@router.get("/notifications")
async def list_notifications(db: AsyncSession = Depends(get_db)):
    configs = await crud.get_notification_configs(db)
    return [_serialize_config(c) for c in configs]


@router.post("/notifications", status_code=201)
async def create_notification(data: NotificationCreate, db: AsyncSession = Depends(get_db)):
    valid_backends = {"console", "gotify", "telegram", "ntfy", "webhook"}
    if data.backend not in valid_backends:
        raise HTTPException(400, f"Backend muss eines von {valid_backends} sein")
    cfg = await crud.create_notification_config(db, data)
    return _serialize_config(cfg)


@router.put("/notifications/{config_id}")
async def update_notification(config_id: int, data: NotificationUpdate, db: AsyncSession = Depends(get_db)):
    cfg = await crud.update_notification_config(db, config_id, data)
    if not cfg:
        raise HTTPException(404, "Benachrichtigungskonfiguration nicht gefunden")
    return _serialize_config(cfg)


@router.delete("/notifications/{config_id}")
async def delete_notification(config_id: int, db: AsyncSession = Depends(get_db)):
    if not await crud.delete_notification_config(db, config_id):
        raise HTTPException(404, "Benachrichtigungskonfiguration nicht gefunden")
    return {"ok": True}


@router.post("/notifications/{config_id}/test")
async def test_notification(config_id: int, db: AsyncSession = Depends(get_db)):
    cfg = await crud.get_notification_config(db, config_id)
    if not cfg:
        raise HTTPException(404, "Benachrichtigungskonfiguration nicht gefunden")

    from ..services.monitor_manager import manager
    success = await manager.test_notification(cfg)
    if not success:
        raise HTTPException(500, "Testbenachrichtigung fehlgeschlagen")
    return {"ok": True, "message": "Testbenachrichtigung gesendet"}

"""Monitor manager: wraps BandWacht instances for web control."""

import asyncio
import json
import logging
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Callable, Optional

import websockets
from sqlalchemy.ext.asyncio import AsyncSession

# Add bandwacht root to path
sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent.parent))

from bandwacht import (  # noqa: E402
    BandWacht,
    ConsoleNotification,
    DetectionEvent,
    GotifyNotification,
    NotificationBackend,
    NtfyNotification,
    TelegramNotification,
    WatchTarget,
    WebhookNotification,
)

from .. import crud  # noqa: E402
from ..database import async_session  # noqa: E402

logger = logging.getLogger("bandwacht.web.manager")


class DatabaseNotifier(NotificationBackend):
    """Captures detection events into the database and broadcasts to WebSocket clients."""

    def __init__(self, instance_id: int, target_map: dict[float, int],
                 on_event: Optional[Callable] = None):
        self.instance_id = instance_id
        self.target_map = target_map  # freq_hz -> target db id
        self.on_event = on_event

    async def send(self, event: DetectionEvent) -> bool:
        target_id = self.target_map.get(event.freq_hz)
        async with async_session() as db:
            db_event = await crud.create_event(
                db,
                instance_id=self.instance_id,
                target_id=target_id,
                timestamp=event.timestamp,
                freq_hz=event.freq_hz,
                peak_db=event.peak_db,
                bandwidth_hz=event.bandwidth_hz,
                duration_s=event.duration_s,
                target_label=event.target_label,
                recording_file=event.recording_file,
            )
            if self.on_event:
                await self.on_event({
                    "type": "detection",
                    "instance_id": self.instance_id,
                    "event_id": db_event.id,
                    "timestamp": event.timestamp.isoformat(),
                    "freq_hz": event.freq_hz,
                    "peak_db": event.peak_db,
                    "bandwidth_hz": event.bandwidth_hz,
                    "duration_s": event.duration_s,
                    "target_label": event.target_label,
                })
        return True


class WebBandWacht(BandWacht):
    """Extended BandWacht that exposes FFT data via callback."""

    def __init__(self, *args, on_fft_callback: Optional[Callable] = None,
                 on_connected_callback: Optional[Callable] = None, **kwargs):
        super().__init__(*args, **kwargs)
        self._on_fft = on_fft_callback
        self._on_connected = on_connected_callback
        self._last_fft: Optional[list] = None
        self._fft_frame_count = 0

    def _init_analyzer(self):
        super()._init_analyzer()
        if self._on_connected:
            asyncio.ensure_future(self._on_connected(self.receiver_config))

    async def _handle_fft(self, data: bytes):
        """Handle FFT data: run analysis and forward to web callback."""
        if self.analyzer is None:
            return

        fft_data = self._process_fft_data(data)
        if fft_data is None:
            return

        self.fft_count += 1
        self._fft_frame_count += 1

        # Log first frame for debugging
        if self._fft_frame_count == 1:
            sample = fft_data[:10].tolist() if len(fft_data) >= 10 else fft_data.tolist()
            logger.info(f"First FFT frame: {len(fft_data)} bins, "
                        f"min={float(fft_data.min()):.1f}, max={float(fft_data.max()):.1f}, "
                        f"mean={float(fft_data.mean()):.1f}, sample={sample}")

        # Run analysis (replicate parent logic)
        if self.targets:
            events = self.analyzer.analyze_band(fft_data, self.targets)
            for event in events:
                self.event_count += 1
                await self._notify_all(event)
                recording_file = ""
                if self.recorder:
                    recording_file = self.recorder.start_recording(
                        event.target_label, event.freq_hz
                    )
                    event.recording_file = recording_file
                self._log_csv(event, recording_file)

        # Full band scan (same as parent: every ~1s at 9fps)
        if self.scan_full_band and self.fft_count % 10 == 0:
            signals = self.analyzer.scan_full_band(
                fft_data, threshold_db=self.threshold_db
            )
            for sig in signals:
                freq_mhz = sig["freq_hz"] / 1e6
                logger.debug(
                    f"  Signal: {freq_mhz:.4f} MHz "
                    f"({sig['peak_db']:.1f} dB, "
                    f"BW: {sig['bandwidth_hz']/1e3:.1f} kHz)"
                )

        # Forward to web callback
        if self._on_fft:
            await self._on_fft(fft_data.tolist())


class MonitorManager:
    """Manages lifecycle of WebBandWacht instances."""

    def __init__(self):
        self._instances: dict[int, WebBandWacht] = {}
        self._tasks: dict[int, asyncio.Task] = {}
        self._fft_subscribers: dict[int, set[Callable]] = {}
        self._event_subscribers: set[Callable] = set()

    def is_running(self, instance_id: int) -> bool:
        task = self._tasks.get(instance_id)
        return task is not None and not task.done()

    async def start_instance(self, instance_id: int, db: AsyncSession):
        if self.is_running(instance_id):
            return

        inst = await crud.get_instance(db, instance_id)
        if not inst:
            raise ValueError(f"Instance {instance_id} not found")

        targets_db = await crud.get_targets(db, instance_id=instance_id)
        settings = await crud.get_settings(db)
        notif_configs = await crud.get_notification_configs(db)

        watch_targets = []
        target_map: dict[float, int] = {}
        for t in targets_db:
            if not t.enabled:
                continue
            wt = WatchTarget(
                freq_hz=t.freq_hz,
                bandwidth_hz=t.bandwidth_hz,
                label=t.label,
                threshold_db=t.threshold_db,
            )
            watch_targets.append(wt)
            target_map[t.freq_hz] = t.id

        # Build notifiers
        notifiers: list[NotificationBackend] = []

        # DB notifier always first
        db_notifier = DatabaseNotifier(
            instance_id=instance_id,
            target_map=target_map,
            on_event=self._broadcast_event,
        )
        notifiers.append(db_notifier)

        # External notifiers from config
        for cfg in notif_configs:
            if not cfg.enabled:
                continue
            n = self._build_notifier(cfg)
            if n:
                notifiers.append(n)

        async def on_fft(fft_data: list):
            await self._broadcast_fft(instance_id, fft_data)

        async def on_connected(receiver_config):
            async with async_session() as session:
                await crud.update_instance_connection(
                    session, instance_id, True,
                    center_freq=receiver_config.center_freq,
                    bandwidth=receiver_config.bandwidth,
                    fft_size=receiver_config.fft_size,
                )

        monitor = WebBandWacht(
            url=inst.url,
            targets=watch_targets,
            scan_full_band=settings.scan_full_band,
            threshold_db=settings.threshold_db,
            hysteresis_db=settings.hysteresis_db,
            hold_time_s=settings.hold_time_s,
            cooldown_s=settings.cooldown_s,
            notifiers=notifiers,
            record=settings.record_enabled,
            desired_profile=inst.desired_profile,
            on_fft_callback=on_fft,
            on_connected_callback=on_connected,
        )

        self._instances[instance_id] = monitor
        self._tasks[instance_id] = asyncio.create_task(
            self._run_monitor(instance_id, monitor)
        )
        logger.info(f"Started monitoring instance {inst.name} ({inst.url})")

    async def _run_monitor(self, instance_id: int, monitor: WebBandWacht):
        try:
            await monitor.run()
        except asyncio.CancelledError:
            monitor.stop()
        except Exception as e:
            logger.error(f"Monitor {instance_id} error: {e}")
        finally:
            async with async_session() as session:
                await crud.update_instance_connection(session, instance_id, False)
            self._instances.pop(instance_id, None)
            self._tasks.pop(instance_id, None)

    async def stop_instance(self, instance_id: int, db: AsyncSession):
        monitor = self._instances.get(instance_id)
        task = self._tasks.get(instance_id)

        if monitor:
            monitor.stop()
        if task and not task.done():
            task.cancel()
            try:
                await task
            except asyncio.CancelledError:
                pass

        await crud.update_instance_connection(db, instance_id, False)
        self._instances.pop(instance_id, None)
        self._tasks.pop(instance_id, None)

    async def stop_all(self):
        for instance_id in list(self._tasks.keys()):
            monitor = self._instances.get(instance_id)
            task = self._tasks.get(instance_id)
            if monitor:
                monitor.stop()
            if task:
                task.cancel()
        self._instances.clear()
        self._tasks.clear()

    # --- FFT streaming ---

    def subscribe_fft(self, instance_id: int, callback: Callable):
        if instance_id not in self._fft_subscribers:
            self._fft_subscribers[instance_id] = set()
        self._fft_subscribers[instance_id].add(callback)

    def unsubscribe_fft(self, instance_id: int, callback: Callable):
        subs = self._fft_subscribers.get(instance_id)
        if subs:
            subs.discard(callback)

    async def _broadcast_fft(self, instance_id: int, fft_data: list):
        subs = self._fft_subscribers.get(instance_id, set())
        if not hasattr(self, '_fft_log_count'):
            self._fft_log_count = {}
        count = self._fft_log_count.get(instance_id, 0) + 1
        self._fft_log_count[instance_id] = count
        if count == 1:
            logger.info(f"First FFT broadcast for instance {instance_id}: {len(fft_data)} bins, {len(subs)} subscriber(s)")
        for cb in list(subs):
            try:
                await cb(fft_data)
            except Exception:
                subs.discard(cb)

    # --- Event streaming ---

    def subscribe_events(self, callback: Callable):
        self._event_subscribers.add(callback)

    def unsubscribe_events(self, callback: Callable):
        self._event_subscribers.discard(callback)

    async def _broadcast_event(self, event_data: dict):
        for cb in list(self._event_subscribers):
            try:
                await cb(event_data)
            except Exception:
                self._event_subscribers.discard(cb)

    # --- Notification test ---

    async def test_notification(self, cfg) -> bool:
        config_data = json.loads(cfg.config_json) if isinstance(cfg.config_json, str) else cfg.config_json
        n = self._build_notifier_from_data(cfg.backend, config_data)
        if not n:
            return False

        test_event = DetectionEvent(
            timestamp=datetime.now(timezone.utc),
            freq_hz=145_500_000,
            peak_db=-45.0,
            bandwidth_hz=12000,
            duration_s=3.5,
            target_label="Test-Signal",
        )
        return await n.send(test_event)

    def _build_notifier(self, cfg) -> Optional[NotificationBackend]:
        config_data = json.loads(cfg.config_json) if isinstance(cfg.config_json, str) else cfg.config_json
        return self._build_notifier_from_data(cfg.backend, config_data)

    def _build_notifier_from_data(self, backend: str, config: dict) -> Optional[NotificationBackend]:
        try:
            if backend == "console":
                return ConsoleNotification()
            elif backend == "gotify":
                return GotifyNotification(url=config["url"], token=config["token"])
            elif backend == "telegram":
                return TelegramNotification(bot_token=config["bot_token"], chat_id=config["chat_id"])
            elif backend == "ntfy":
                return NtfyNotification(
                    topic=config["topic"],
                    server=config.get("server", "https://ntfy.sh"),
                )
            elif backend == "webhook":
                return WebhookNotification(url=config["url"])
        except (KeyError, TypeError) as e:
            logger.warning(f"Cannot build {backend} notifier: {e}")
        return None

    def get_monitor(self, instance_id: int) -> Optional[WebBandWacht]:
        return self._instances.get(instance_id)


async def fetch_profiles_from_url(url: str, timeout: float = 5.0) -> list[dict]:
    """Connect to an OpenWebRX instance and fetch its available profiles."""
    base_url = url.rstrip("/")
    if base_url.startswith("https://"):
        ws_url = base_url.replace("https://", "wss://") + "/ws/"
    elif base_url.startswith("http://"):
        ws_url = base_url.replace("http://", "ws://") + "/ws/"
    elif base_url.startswith("ws://") or base_url.startswith("wss://"):
        ws_url = base_url + "/ws/"
    else:
        ws_url = "ws://" + base_url + "/ws/"

    try:
        async with websockets.connect(
            ws_url,
            ping_interval=None,
            max_size=2**20,
            additional_headers={"User-Agent": "BandWacht/1.0 (FunkPilot/OE8YML)"},
        ) as ws:
            await ws.send("SERVER DE CLIENT client=bandwacht type=receiver")
            deadline = asyncio.get_running_loop().time() + timeout
            while asyncio.get_running_loop().time() < deadline:
                try:
                    msg = await asyncio.wait_for(
                        ws.recv(),
                        timeout=deadline - asyncio.get_running_loop().time(),
                    )
                except asyncio.TimeoutError:
                    break
                if isinstance(msg, str) and msg.startswith("{"):
                    try:
                        data = json.loads(msg)
                        if data.get("type") == "profiles" and isinstance(data.get("value"), list):
                            return data["value"]
                    except json.JSONDecodeError:
                        pass
    except Exception as e:
        logger.warning(f"Failed to fetch profiles from {url}: {e}")
    return []


# Singleton
manager = MonitorManager()

import { useCallback, useEffect, useState } from 'react'
import { Plus, Trash2, Send } from 'lucide-react'
import { notifications as api } from '../../api/client'
import { UI } from '../../utils/strings'
import StatusBadge from '../shared/StatusBadge'
import ConfirmDialog from '../shared/ConfirmDialog'
import type { NotificationConfig as NotifType } from '../../types'

const BACKENDS = [
  { value: 'console', label: 'Konsole' },
  { value: 'gotify', label: 'Gotify', fields: ['url', 'token'] },
  { value: 'telegram', label: 'Telegram', fields: ['bot_token', 'chat_id'] },
  { value: 'ntfy', label: 'ntfy', fields: ['topic', 'server'] },
  { value: 'webhook', label: 'Webhook', fields: ['url'] },
]

export default function NotificationConfig() {
  const [configs, setConfigs] = useState<NotifType[]>([])
  const [deleteId, setDeleteId] = useState<number | null>(null)
  const [addBackend, setAddBackend] = useState('')
  const [testing, setTesting] = useState<number | null>(null)

  const load = useCallback(async () => {
    const data = await api.list()
    setConfigs(data)
  }, [])

  useEffect(() => { load() }, [load])

  const handleAdd = async () => {
    if (!addBackend) return
    await api.create({ backend: addBackend, enabled: true, config_json: {} })
    setAddBackend('')
    load()
  }

  const handleDelete = async () => {
    if (deleteId == null) return
    await api.delete(deleteId)
    setDeleteId(null)
    load()
  }

  const handleToggle = async (cfg: NotifType) => {
    await api.update(cfg.id, { enabled: !cfg.enabled })
    load()
  }

  const handleTest = async (id: number) => {
    setTesting(id)
    try {
      await api.test(id)
    } catch (_) {
      // ignore
    } finally {
      setTesting(null)
    }
  }

  const handleConfigChange = async (cfg: NotifType, key: string, value: string) => {
    const newConfig = { ...cfg.config_json, [key]: value }
    await api.update(cfg.id, { config_json: newConfig })
    load()
  }

  return (
    <>
      <div className="flex items-center gap-2 mb-3">
        <select className="input" value={addBackend} onChange={e => setAddBackend(e.target.value)}>
          <option value="">Backend wählen...</option>
          {BACKENDS.map(b => (
            <option key={b.value} value={b.value}>{b.label}</option>
          ))}
        </select>
        <button onClick={handleAdd} disabled={!addBackend} className="btn-primary flex items-center gap-1.5">
          <Plus className="w-3.5 h-3.5" />
          Hinzufügen
        </button>
      </div>

      <div className="space-y-3">
        {configs.map(cfg => {
          const backendDef = BACKENDS.find(b => b.value === cfg.backend)
          return (
            <div key={cfg.id} className="p-3 bg-sdr-bg rounded-lg border border-sdr-border space-y-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <StatusBadge active={cfg.enabled} />
                  <span className="text-sm font-medium">{backendDef?.label ?? cfg.backend}</span>
                </div>
                <div className="flex items-center gap-1">
                  <button
                    onClick={() => handleToggle(cfg)}
                    className="btn-ghost text-xs px-2 py-1"
                  >
                    {cfg.enabled ? 'Deaktivieren' : 'Aktivieren'}
                  </button>
                  <button
                    onClick={() => handleTest(cfg.id)}
                    disabled={testing === cfg.id}
                    className="p-1.5 text-sdr-muted hover:text-sdr-cyan transition-colors"
                    title={UI.cfg_test}
                  >
                    <Send className="w-3.5 h-3.5" />
                  </button>
                  <button
                    onClick={() => setDeleteId(cfg.id)}
                    className="p-1.5 text-sdr-muted hover:text-sdr-red transition-colors"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>

              {backendDef?.fields && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {backendDef.fields.map(field => (
                    <div key={field}>
                      <label className="label">{field}</label>
                      <input
                        className="input w-full"
                        value={(cfg.config_json as Record<string, string>)[field] ?? ''}
                        onChange={e => handleConfigChange(cfg, field, e.target.value)}
                        onBlur={e => handleConfigChange(cfg, field, e.target.value)}
                        placeholder={field}
                      />
                    </div>
                  ))}
                </div>
              )}
            </div>
          )
        })}
      </div>

      <ConfirmDialog
        open={deleteId != null}
        message={UI.confirm_delete}
        onConfirm={handleDelete}
        onCancel={() => setDeleteId(null)}
      />
    </>
  )
}

const BASE = '/api/v1'

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    ...options,
  })
  if (!res.ok) {
    const body = await res.json().catch(() => ({ detail: res.statusText }))
    throw new Error(body.detail || `HTTP ${res.status}`)
  }
  return res.json()
}

// --- Instances ---

export const instances = {
  list: () => request<import('../types').SdrInstance[]>('/instances'),
  get: (id: number) => request<import('../types').SdrInstance>(`/instances/${id}`),
  create: (data: { name: string; url: string; enabled?: boolean; desired_profile?: string | null }) =>
    request<import('../types').SdrInstance>('/instances', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  update: (id: number, data: Partial<{ name: string; url: string; enabled: boolean; desired_profile: string | null }>) =>
    request<import('../types').SdrInstance>(`/instances/${id}`, {
      method: 'PUT',
      body: JSON.stringify(data),
    }),
  delete: (id: number) => request<{ ok: boolean }>(`/instances/${id}`, { method: 'DELETE' }),
  start: (id: number) => request<{ ok: boolean }>(`/instances/${id}/start`, { method: 'POST' }),
  stop: (id: number) => request<{ ok: boolean }>(`/instances/${id}/stop`, { method: 'POST' }),
  status: (id: number) => request<any>(`/instances/${id}/status`),
  profiles: (id: number) => request<import('../types').AvailableProfile[]>(`/instances/${id}/profiles`),
}

// --- Targets ---

export const targets = {
  list: (instanceId?: number) =>
    request<import('../types').WatchTarget[]>(
      `/targets${instanceId != null ? `?instance_id=${instanceId}` : ''}`
    ),
  create: (data: {
    instance_id: number
    freq_hz: number
    bandwidth_hz?: number
    label?: string
    threshold_db?: number
    enabled?: boolean
  }) =>
    request<import('../types').WatchTarget>('/targets', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  update: (id: number, data: Partial<import('../types').WatchTarget>) =>
    request<import('../types').WatchTarget>(`/targets/${id}`, {
      method: 'PUT',
      body: JSON.stringify(data),
    }),
  delete: (id: number) => request<{ ok: boolean }>(`/targets/${id}`, { method: 'DELETE' }),
}

// --- Events ---

export const events = {
  list: (params?: {
    page?: number
    page_size?: number
    instance_id?: number
    freq_min?: number
    freq_max?: number
    date_from?: string
    date_to?: string
    label?: string
  }) => {
    const searchParams = new URLSearchParams()
    if (params) {
      Object.entries(params).forEach(([k, v]) => {
        if (v != null) searchParams.set(k, String(v))
      })
    }
    const qs = searchParams.toString()
    return request<import('../types').PaginatedResponse<import('../types').DetectionEvent>>(
      `/events${qs ? `?${qs}` : ''}`
    )
  },
  stats: () => request<import('../types').EventStats>('/events/stats'),
  exportCsv: () => `${BASE}/events/export`,
}

// --- Recordings ---

export const recordings = {
  list: () => request<string[]>('/recordings'),
  url: (filename: string) => `${BASE}/recordings/${encodeURIComponent(filename)}`,
  delete: (filename: string) =>
    request<{ ok: boolean }>(`/recordings/${encodeURIComponent(filename)}`, { method: 'DELETE' }),
}

